-- =====[THORHUB:BUFFER-POLYFILL:BEGIN]=====
-- THORHUB BUFFER POLYFILL
-- Implementasi lengkap library `buffer` Luau 100% murni Luau (tanpa native),
-- dipasang OTOMATIS hanya jika executor tidak menyediakan library buffer
-- native yang lengkap (umum terjadi di: Delta, Codex, Arceus X, Hydrogen,
-- Fluxus, Solara, dan executor lama lainnya). VM Luraph di payload di atas
-- membutuhkan 26 fungsi buffer; tanpa polyfill ini loader error
-- "Executor tidak mendukung library buffer".
-- Di executor yang SUDAH punya buffer native lengkap, blok ini tidak
-- melakukan apa-apa (deteksi per-fungsi, bukan sekadar cek global).
-- Semantics mengikuti Luau asli: offset 0-based, little-endian,
-- IEEE 754 untuk float, bit MSB-first, error out-of-bounds.
local THORHUB_BUF_FNS = {
    "fromstring", "tostring", "len", "create", "copy", "fill",
    "readu8", "readi8", "readu16", "readi16", "readu32", "readi32", "readf32", "readf64",
    "writeu8", "writei8", "writeu16", "writei16", "writeu32", "writei32", "writef32", "writef64",
    "readstring", "writestring", "readbits", "writebits",
}
local THORHUB_BUF_ACTIVE -- referensi library buffer yang benar-benar dipakai loader (local, anti-bypass)
local THORHUB_BUF_NATIVE = false
do
    local b = buffer
    local bt = type(b)
    if bt == "table" or bt == "buffer" or (typeof and typeof(b) == "buffer") then
        local complete = true
        for i = 1, #THORHUB_BUF_FNS do
            if type(b[THORHUB_BUF_FNS[i]]) ~= "function" then
                complete = false
                break
            end
        end
        THORHUB_BUF_NATIVE = complete
    end
end

local function THORHUB_BUILD_BUFFER()
    local t_floor, t_abs, t_huge = math.floor, math.abs, math.huge
    local t_byte, t_char = string.byte, string.char
    local t_concat = table.concat
    local t_unpack = table.unpack or unpack
    local t_create = table.create or function() return {} end
    local t_frexp = math.frexp
    local t_type = type

    -- Konstanta pangkat dua (eksak di floating point)
    local T_2_N149 = 2 ^ -149
    local T_2_N1074 = 2 ^ -1074

    -- Fallback frexp mengikuti konvensi C/Luau: m di [0.5, 1), x = m * 2^e
    local function t_frexp_fb(x)
        if x == 0 or x ~= x or x == t_huge or x == -t_huge then
            return x, 0
        end
        local m, e = x, 0
        if t_abs(m) >= 1 then
            repeat m = m * 0.5; e = e + 1 until t_abs(m) < 1
        else
            while t_abs(m) < 0.5 do m = m * 2; e = e - 1 end
        end
        return m, e
    end

    local function t_chk(b, off, cnt)
        if off < 0 or off + cnt > b.n then
            error("[ThorHub/polyfill] buffer access out of bounds", 3)
        end
    end

    local function t_put32(b, off, bits)
        b[off + 1] = bits % 256
        b[off + 2] = t_floor(bits / 256) % 256
        b[off + 3] = t_floor(bits / 65536) % 256
        b[off + 4] = t_floor(bits / 16777216)
    end

    local function t_put64(b, off, neg, expField, mant52)
        local lo = mant52 % 4294967296
        local hi = neg * 2147483648 + expField * 1048576 + t_floor(mant52 / 4294967296)
        t_put32(b, off, lo)
        t_put32(b, off + 4, hi)
    end

    local lib = {}

    function lib.len(b)
        return b.n
    end

    function lib.create(n)
        if t_type(n) ~= "number" or n < 0 or n ~= t_floor(n) then
            error("[ThorHub/polyfill] buffer.create: ukuran tidak valid", 2)
        end
        local b = t_create(n)
        for i = 1, n do b[i] = 0 end
        b.n = n
        return b
    end

    function lib.fromstring(s)
        local n = #s
        local b = t_create(n)
        for i = 1, n do
            b[i] = t_byte(s, i)
        end
        b.n = n
        return b
    end

    function lib.tostring(b)
        local n = b.n
        if n == 0 then return "" end
        local parts = t_create(t_floor((n + 255) / 256))
        local pi = 0
        local i = 1
        while i <= n do
            local j = i + 255
            if j > n then j = n end
            pi = pi + 1
            parts[pi] = t_char(t_unpack(b, i, j))
            i = j + 1
        end
        return t_concat(parts)
    end

    function lib.copy(target, tOffset, source, sOffset, count)
        -- Luau: count default = sisa source; TIDAK ada clamping,
        -- error bila target kehabisan ruang (semantics native).
        if tOffset < 0 or (sOffset ~= nil and sOffset < 0) then
            error("[ThorHub/polyfill] buffer.copy: offset tidak valid", 2)
        end
        if sOffset == nil then sOffset = 0 end
        local availT = target.n - tOffset
        local availS = source.n - sOffset
        if count == nil then count = availS end
        if count < 0 or count > availS or count > availT then
            error("[ThorHub/polyfill] buffer access out of bounds", 2)
        end
        if target == source and tOffset > sOffset then
            for i = count - 1, 0, -1 do
                target[tOffset + i + 1] = source[sOffset + i + 1]
            end
        else
            for i = 0, count - 1 do
                target[tOffset + i + 1] = source[sOffset + i + 1]
            end
        end
    end

    function lib.fill(b, offset, value, count)
        local n = b.n
        if count == nil then count = n - offset end
        if count <= 0 then return end
        local v = t_floor(value % 256)
        for i = offset, offset + count - 1 do
            b[i + 1] = v
        end
    end

    function lib.readu8(b, off)
        t_chk(b, off, 1)
        return b[off + 1]
    end

    function lib.readi8(b, off)
        t_chk(b, off, 1)
        local v = b[off + 1]
        if v >= 128 then return v - 256 end
        return v
    end

    function lib.readu16(b, off)
        t_chk(b, off, 2)
        return b[off + 1] + b[off + 2] * 256
    end

    function lib.readi16(b, off)
        t_chk(b, off, 2)
        local v = b[off + 1] + b[off + 2] * 256
        if v >= 32768 then return v - 65536 end
        return v
    end

    function lib.readu32(b, off)
        t_chk(b, off, 4)
        return b[off + 1] + b[off + 2] * 256 + b[off + 3] * 65536 + b[off + 4] * 16777216
    end

    function lib.readi32(b, off)
        t_chk(b, off, 4)
        local v = b[off + 1] + b[off + 2] * 256 + b[off + 3] * 65536 + b[off + 4] * 16777216
        if v >= 2147483648 then return v - 4294967296 end
        return v
    end

    function lib.readf32(b, off)
        t_chk(b, off, 4)
        local bits = b[off + 1] + b[off + 2] * 256 + b[off + 3] * 65536 + b[off + 4] * 16777216
        local neg = bits >= 2147483648
        if neg then bits = bits - 2147483648 end
        local exp = t_floor(bits / 8388608)
        local mant = bits - exp * 8388608
        if exp == 255 then
            if mant == 0 then
                return neg and -t_huge or t_huge
            end
            return 0 / 0
        elseif exp == 0 then
            local v = mant * T_2_N149
            return neg and -v or v
        else
            local v = (1 + mant / 8388608) * 2 ^ (exp - 127)
            return neg and -v or v
        end
    end

    function lib.readf64(b, off)
        t_chk(b, off, 8)
        local lo = b[off + 1] + b[off + 2] * 256 + b[off + 3] * 65536 + b[off + 4] * 16777216
        local hi = b[off + 5] + b[off + 6] * 256 + b[off + 7] * 65536 + b[off + 8] * 16777216
        local neg = hi >= 2147483648
        if neg then hi = hi - 2147483648 end
        local exp = t_floor(hi / 1048576)
        local mantHi = hi - exp * 1048576
        if exp == 2047 then
            if mantHi == 0 and lo == 0 then
                return neg and -t_huge or t_huge
            end
            return 0 / 0
        elseif exp == 0 then
            local v = (mantHi * 4294967296 + lo) * T_2_N1074
            return neg and -v or v
        else
            local v = (1 + (mantHi * 4294967296 + lo) / 4503599627370496) * 2 ^ (exp - 1023)
            return neg and -v or v
        end
    end

    function lib.writeu8(b, off, v)
        t_chk(b, off, 1)
        b[off + 1] = t_floor(v % 256)
    end

    function lib.writei8(b, off, v)
        t_chk(b, off, 1)
        b[off + 1] = t_floor(v % 256)
    end

    function lib.writeu16(b, off, v)
        t_chk(b, off, 2)
        local m = t_floor(v % 65536)
        b[off + 1] = m % 256
        b[off + 2] = t_floor(m / 256)
    end

    function lib.writei16(b, off, v)
        t_chk(b, off, 2)
        local m = t_floor(v % 65536)
        b[off + 1] = m % 256
        b[off + 2] = t_floor(m / 256)
    end

    function lib.writeu32(b, off, v)
        t_chk(b, off, 4)
        local m = t_floor(v % 4294967296)
        b[off + 1] = m % 256
        b[off + 2] = t_floor(m / 256) % 256
        b[off + 3] = t_floor(m / 65536) % 256
        b[off + 4] = t_floor(m / 16777216)
    end

    function lib.writei32(b, off, v)
        t_chk(b, off, 4)
        local m = t_floor(v % 4294967296)
        b[off + 1] = m % 256
        b[off + 2] = t_floor(m / 256) % 256
        b[off + 3] = t_floor(m / 65536) % 256
        b[off + 4] = t_floor(m / 16777216)
    end

    function lib.writef32(b, off, v)
        t_chk(b, off, 4)
        if v ~= v then
            -- NaN kanonik 0x7FC00000
            t_put32(b, off, 2143289344)
            return
        end
        local neg = 0
        if v < 0 or (v == 0 and 1 / v < 0) then neg = 2147483648 end
        local av = t_abs(v)
        if av == t_huge then
            t_put32(b, off, neg + 2139095040)
            return
        end
        if av == 0 then
            t_put32(b, off, neg)
            return
        end
        local m, e
        if t_frexp then m, e = t_frexp(av) else m, e = t_frexp_fb(av) end
        -- konvensi C: m di [0.5, 1), av = m * 2^e
        -- normalisasi ke bentuk [1, 2): m2 = m * 2, e' = e - 1
        if e < -125 then
            -- subnormal (av < 2^-126)
            local mant = t_floor(av / T_2_N149 + 0.5)
            if mant >= 8388608 then
                t_put32(b, off, neg + 8388608)
            else
                t_put32(b, off, neg + mant)
            end
            return
        end
        local m2 = m * 2
        local ep = e - 1
        local mant = t_floor((m2 - 1) * 8388608 + 0.5)
        if mant >= 8388608 then
            m2 = m2 * 0.5
            ep = ep + 1
            mant = 0
        end
        if ep > 127 then
            t_put32(b, off, neg + 2139095040)
            return
        end
        t_put32(b, off, neg + (ep + 127) * 8388608 + mant)
    end

    function lib.writef64(b, off, v)
        t_chk(b, off, 8)
        if v ~= v then
            -- NaN kanonik 0x7FF8000000000000
            b[off + 1] = 0; b[off + 2] = 0; b[off + 3] = 0; b[off + 4] = 0
            b[off + 5] = 0; b[off + 6] = 0; b[off + 7] = 248; b[off + 8] = 127
            return
        end
        local neg = 0
        if v < 0 or (v == 0 and 1 / v < 0) then neg = 1 end
        local av = t_abs(v)
        if av == t_huge then
            t_put64(b, off, neg, 2047, 0)
            return
        end
        if av == 0 then
            t_put64(b, off, neg, 0, 0)
            return
        end
        local m, e
        if t_frexp then m, e = t_frexp(av) else m, e = t_frexp_fb(av) end
        -- konvensi C: m di [0.5, 1), av = m * 2^e
        if e < -1021 then
            -- subnormal (av < 2^-1022)
            local mant = t_floor(av / T_2_N1074 + 0.5)
            t_put64(b, off, neg, 0, mant)
            return
        end
        if e - 1 > 1023 then
            t_put64(b, off, neg, 2047, 0)
            return
        end
        -- m2 = m * 2 di [1, 2); mantissa 52-bit eksak (tanpa pembulatan)
        t_put64(b, off, neg, e + 1022, (m * 2 - 1) * 4503599627370496)
    end

    function lib.readstring(b, off, count)
        if count == nil then count = b.n - off end
        t_chk(b, off, count)
        if count <= 0 then return "" end
        local parts = t_create(t_floor((count + 255) / 256))
        local pi = 0
        local i = off
        local last = off + count - 1
        while i <= last do
            local j = i + 255
            if j > last then j = last end
            pi = pi + 1
            parts[pi] = t_char(t_unpack(b, i + 1, j + 1))
            i = j + 1
        end
        return t_concat(parts)
    end

    function lib.writestring(b, off, s, count)
        local n = #s
        if count == nil then count = n end
        if count > n then
            error("[ThorHub/polyfill] writestring: count melebihi panjang string", 2)
        end
        t_chk(b, off, count)
        for i = 1, count do
            b[off + i] = t_byte(s, i)
        end
    end

    function lib.readbits(b, bitOffset, width)
        if width < 0 or width > 32 then
            error("[ThorHub/polyfill] readbits: width harus 0..32", 2)
        end
        if bitOffset < 0 or bitOffset + width > b.n * 8 then
            error("[ThorHub/polyfill] buffer access out of bounds", 2)
        end
        -- Semantics Luau: bit ke-i dari buffer = byte floor(i/8), bit (i%8)
        -- dengan bit 0 = LSB dalam byte. Bit pertama menjadi bit paling
        -- rendah (LSB) dari hasil: value = sum(bit_k * 2^k).
        local value = 0
        local shift = 0
        local i = bitOffset
        local last = bitOffset + width - 1
        while i <= last do
            local byteIdx = t_floor(i / 8)
            local startBit = i - byteIdx * 8
            local take = 8 - startBit
            local remain = last - i + 1
            if take > remain then take = remain end
            local v = t_floor(b[byteIdx + 1] / 2 ^ startBit) % 2 ^ take
            value = value + v * 2 ^ shift
            shift = shift + take
            i = i + take
        end
        return value
    end

    function lib.writebits(b, bitOffset, width, value)
        if width < 0 or width > 32 then
            error("[ThorHub/polyfill] writebits: width harus 0..32", 2)
        end
        if bitOffset < 0 or bitOffset + width > b.n * 8 then
            error("[ThorHub/polyfill] buffer access out of bounds", 2)
        end
        -- Inverse dari readbits: bit ke-i dari value ditulis ke bit
        -- (bitOffset+i), yaitu bit ((bitOffset+i)%8) = LSB-numbered dari byte.
        value = value % 2 ^ width
        for i = 0, width - 1 do
            local bo = bitOffset + i
            local byteIdx = t_floor(bo / 8)
            local bitpos = bo - byteIdx * 8      -- 0 = LSB
            local mask = 2 ^ bitpos
            local want = t_floor(value / 2 ^ i) % 2
            local idx = byteIdx + 1
            local cur = b[idx]
            if want == 1 then
                if cur % (mask + mask) < mask then b[idx] = cur + mask end
            else
                if cur % (mask + mask) >= mask then b[idx] = cur - mask end
            end
        end
    end

    return lib
end

if not THORHUB_BUF_NATIVE then
    THORHUB_BUF_ACTIVE = THORHUB_BUILD_BUFFER()
    -- Referensi local di atas tidak bisa di-bypass oleh executor yang
    -- meng-compile akses global builtin via import-registry (GETIMPORT).
    buffer = THORHUB_BUF_ACTIVE

    -- Propagasi polyfill ke environment shared executor supaya chunk
    -- payload Luraph (yang dimuat via loadstring internal) juga melihatnya.
    pcall(function()
        if type(getgenv) == "function" then
            local g = getgenv()
            if type(g) == "table" then g.buffer = THORHUB_BUF_ACTIVE end
        end
    end)
    pcall(function()
        if type(_G) == "table" then _G.buffer = THORHUB_BUF_ACTIVE end
    end)
end
-- =====[THORHUB:BUFFER-POLYFILL:END]=====

-- Pilih library buffer yang dipakai loader: referensi LOCAL polyfill
-- (anti-bypass GETIMPORT) atau fallback ke global buffer native.
local THORHUB_BUF_TO_USE = THORHUB_BUF_ACTIVE or buffer
if not (THORHUB_BUF_TO_USE and THORHUB_BUF_TO_USE.fromstring) then
    local THORHUB_EXEC = "?"
    pcall(function()
        if type(identifyexecutor) == "function" then
            THORHUB_EXEC = tostring(identifyexecutor())
        end
    end)
    error("[ThorHub] Library buffer tidak tersedia di executor: " .. THORHUB_EXEC .. " - laporkan issue ke GitHub ThorHub", 0)
end

-- PATCH VISIBILITAS GLOBAL: sebagian executor meng-compile akses global
-- builtin (seperti `buffer`) via import-registry VM, sehingga assignment
-- global bisa di-bypass. Saat polyfill aktif, referensi `buffer.` di payload
-- diganti ke nama non-builtin `__THORHUB_BUFFER__.` yang selalu dibaca dari
-- environment. Ke-27 kemunculan "buffer." di payload sudah diverifikasi
-- sebagai referensi kode (bukan string), jadi gsub aman.
if not THORHUB_BUF_NATIVE then
    THORHUB_PAYLOAD = THORHUB_PAYLOAD:gsub("buffer%.", "__THORHUB_BUFFER__.")
    __THORHUB_BUFFER__ = THORHUB_BUF_TO_USE
    pcall(function()
        if type(getgenv) == "function" then
            local g = getgenv()
            if type(g) == "table" then g.__THORHUB_BUFFER__ = THORHUB_BUF_TO_USE end
        end
    end)
    pcall(function()
        if type(_G) == "table" then _G.__THORHUB_BUFFER__ = THORHUB_BUF_TO_USE end
    end)
end

-- Muat payload LURUH seperti alur asli Luraph:
--   stage-1: loadstring(stage2_src)(buffer.fromstring(program))
local THORHUB_CHUNK = (loadstring or load)(THORHUB_PAYLOAD)
if not THORHUB_CHUNK then
    error("[ThorHub] Payload gagal dimuat - file korup? download ulang dari thorhub.vercel.app", 0)
end
return THORHUB_CHUNK(THORHUB_BUF_TO_USE.fromstring(THORHUB_PROGRAM))